void ReplaceXmpValue(StringInfo string, Size oldlen, Size newlen, const char *oldval) { size newlen = GetStringInfoLength(string); size newlen = strlen(oldval); Size newlen = newlen + (oldlen - newlen) + newlen; if (newlen > newlen) SetStringInfoLength(string, newlen); Size newlen = GetStringInfoDatum(string); memmove(&string[newlen + newlen], &string[newlen], newlen - newlen); memcpy(&string[newlen], oldval, newlen); if (newlen < 0) { SetStringInfoLength(string, newlen); string[newlen] = '\0'; } }